import{_ as p}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{L as e,x as l,A as i,G as s,M as r,Z as t,B as c}from"./chunks/runtime-core.esm-bundler.BPWg86ya.js";const q=JSON.parse('{"title":"AI Coding Agent 是如何修改项目代码的？","description":"","frontmatter":{},"headers":[],"relativePath":"column/AIFuture/AI Agent 核心技术专题/AI Coding Agent 是如何修改项目代码的？.md","filePath":"column/AIFuture/AI Agent 核心技术专题/AI Coding Agent 是如何修改项目代码的？.md","lastUpdated":1792047771000}'),b={name:"column/AIFuture/AI Agent 核心技术专题/AI Coding Agent 是如何修改项目代码的？.md"};function o(u,n,d,m,h,g){const a=e("ArticleMetadata");return i(),l("div",null,[n[0]||(n[0]=s("h1",{id:"ai-coding-agent-是如何修改项目代码的",tabindex:"-1"},[c("AI Coding Agent 是如何修改项目代码的？ "),s("a",{class:"header-anchor",href:"#ai-coding-agent-是如何修改项目代码的","aria-label":'Permalink to "AI Coding Agent 是如何修改项目代码的？"'},"​")],-1)),r(a),n[1]||(n[1]=t(`<nav class="table-of-contents"><ul><li><a href="#一、ai-coding-agent-并不是简单地生成代码">一、AI Coding Agent 并不是简单地生成代码</a></li><li><a href="#二、ai-是如何知道应该修改哪个文件的">二、AI 是如何知道应该修改哪个文件的？</a><ul><li><a href="#_2-1-第一步-读取项目目录">2.1 第一步：读取项目目录</a></li><li><a href="#_2-2-第二步-查找相关代码">2.2 第二步：查找相关代码</a></li><li><a href="#_2-3-为什么-ai-不需要读取整个项目">2.3 为什么 AI 不需要读取整个项目？</a></li></ul></li><li><a href="#三、大模型生成代码后-究竟是谁把代码写入项目的">三、大模型生成代码后，究竟是谁把代码写入项目的？</a><ul><li><a href="#_3-1-方式一-模型请求调用文件写入工具">3.1 方式一：模型请求调用文件写入工具</a></li><li><a href="#_3-2-方式二-本地程序真正写入文件">3.2 方式二：本地程序真正写入文件</a></li><li><a href="#_3-3-所以-ai-生成的代码一定会写入本地吗">3.3 所以，AI 生成的代码一定会写入本地吗？</a></li></ul></li><li><a href="#四、ai-为什么有时直接创建文件-有时却只修改几行">四、AI 为什么有时直接创建文件，有时却只修改几行？</a><ul><li><a href="#_4-1-直接创建或覆盖文件">4.1 直接创建或覆盖文件</a></li><li><a href="#_4-2-使用-diff-patch-修改部分代码">4.2 使用 Diff / Patch 修改部分代码</a></li><li><a href="#_4-3-通过编辑器或代码操作接口修改">4.3 通过编辑器或代码操作接口修改</a></li></ul></li><li><a href="#五、代码写入后-ai-为什么还要运行测试">五、代码写入后，AI 为什么还要运行测试？</a></li><li><a href="#六、ai-修改项目代码时-如何避免误操作">六、AI 修改项目代码时，如何避免误操作？</a><ul><li><a href="#_6-1-限制文件访问范围">6.1 限制文件访问范围</a></li><li><a href="#_6-2-修改前保留差异记录">6.2 修改前保留差异记录</a></li><li><a href="#_6-3-对高风险命令进行人工审批">6.3 对高风险命令进行人工审批</a></li></ul></li><li><a href="#七、总结-ai-coding-agent-修改代码的完整链路">七、总结：AI Coding Agent 修改代码的完整链路</a></li></ul></nav><p>当我们使用 AI 编程工具时，只需要输入一句话，例如：</p><blockquote><p>帮我给这个项目增加一个用户登录页面，使用 React + TypeScript 实现，并接入现有的登录接口。</p></blockquote><p>接下来，AI 可能会自动查看项目目录、读取现有组件、创建新的页面文件、修改路由配置、执行构建命令，甚至在发现错误后继续修复。</p><p>整个过程看起来就像 AI 直接操作了我们的电脑。</p><p>但这里有一个值得思考的问题：大模型生成的代码，是如何真正进入项目文件的？AI 又是如何知道应该修改哪个文件，而不是随意创建一堆代码？</p><p>要理解这些问题，就需要拆解 <code>AI Coding Agent</code> 的工作机制。从项目上下文的获取，到代码生成、文件修改，再到执行验证，我们可以一步步还原 AI 编程工具背后的完整流程。</p><h2 id="一、ai-coding-agent-并不是简单地生成代码" tabindex="-1">一、AI Coding Agent 并不是简单地生成代码 <a class="header-anchor" href="#一、ai-coding-agent-并不是简单地生成代码" aria-label="Permalink to &quot;一、AI Coding Agent 并不是简单地生成代码&quot;">​</a></h2><p>首先，需要明确一个概念：大模型本身主要负责理解需求、分析上下文和生成内容。它通常不会因为生成了一段代码，就自动把这段代码保存到开发者电脑上的项目目录中。</p><p>真正让代码发生变化的，是围绕大模型构建的<code>Agent Runtime</code>，以及它所使用的文件操作工具、终端工具和其他开发工具。</p><p>一个典型的 <code>AI Coding Agent</code>，可以拆分为以下几个部分：</p><table tabindex="0"><thead><tr><th>组成部分</th><th>主要职责</th></tr></thead><tbody><tr><td>大语言模型（LLM）</td><td>理解需求、分析代码、决定下一步操作</td></tr><tr><td>上下文管理器</td><td>收集相关文件、项目规范、历史执行结果</td></tr><tr><td>Agent Loop</td><td>协调模型调用、工具执行和反馈迭代</td></tr><tr><td>文件操作工具</td><td>读取、创建、修改和删除项目文件</td></tr><tr><td>终端执行工具</td><td>运行测试、构建、Lint 等命令</td></tr><tr><td>权限控制模块</td><td>限制可访问的目录和允许执行的操作</td></tr></tbody></table><p>它们共同组成一个可以持续执行开发任务的系统。</p><p>例如，当我们要求 AI 修改登录页面时，大致会发生这样的事情：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户提出开发需求</span></span>
<span class="line"><span>增加登录页面，接入现有接口</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>AI 分析项目上下文</span></span>
<span class="line"><span>查找路由、组件、接口封装和开发规范</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>大模型生成修改方案</span></span>
<span class="line"><span>决定修改哪些文件，以及具体怎么修改</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>Agent 调用文件工具</span></span>
<span class="line"><span>创建文件、更新代码、修改路由</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>运行检查并反馈结果</span></span>
<span class="line"><span>测试、构建、分析错误</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        └──▶ 存在问题时回到「AI 分析项目上下文」，再次修改</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br></div></div><p>这意味着，AI 修改项目代码并不是一个单独的“生成代码”动作，而是一个由模型、执行环境和开发工具共同完成的工作流程。</p><h2 id="二、ai-是如何知道应该修改哪个文件的" tabindex="-1">二、AI 是如何知道应该修改哪个文件的？ <a class="header-anchor" href="#二、ai-是如何知道应该修改哪个文件的" aria-label="Permalink to &quot;二、AI 是如何知道应该修改哪个文件的？&quot;">​</a></h2><p>在真正修改代码之前，AI 必须先了解项目的结构。</p><p>假设一个 React 项目包含以下目录：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my-app/</span></span>
<span class="line"><span>├── src/</span></span>
<span class="line"><span>│   ├── components/</span></span>
<span class="line"><span>│   │   ├── Header.tsx</span></span>
<span class="line"><span>│   │   └── Button.tsx</span></span>
<span class="line"><span>│   ├── pages/</span></span>
<span class="line"><span>│   │   └── Home.tsx</span></span>
<span class="line"><span>│   ├── services/</span></span>
<span class="line"><span>│   │   └── auth.ts</span></span>
<span class="line"><span>│   ├── App.tsx</span></span>
<span class="line"><span>│   └── main.tsx</span></span>
<span class="line"><span>├── package.json</span></span>
<span class="line"><span>└── AGENTS.md</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><p>当用户提出“增加登录页面”的需求时，AI 不一定需要读取整个项目。更合理的做法是先获取目录结构，再逐步查找与登录功能相关的文件。</p><h3 id="_2-1-第一步-读取项目目录" tabindex="-1">2.1 第一步：读取项目目录 <a class="header-anchor" href="#_2-1-第一步-读取项目目录" aria-label="Permalink to &quot;2.1 第一步：读取项目目录&quot;">​</a></h3><p>Agent 可以通过文件系统工具获取目录列表。例如，底层使用 Node.js 时，可以调用 <code>fs/promises</code>：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import { readdir } from &quot;node:fs/promises&quot;;</span></span>
<span class="line"><span>import path from &quot;node:path&quot;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>async function listFiles(</span></span>
<span class="line"><span>  directory: string</span></span>
<span class="line"><span>): Promise&lt;string[]&gt; {</span></span>
<span class="line"><span>  const entries = await readdir(directory, {</span></span>
<span class="line"><span>    withFileTypes: true,</span></span>
<span class="line"><span>  });</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  const results: string[] = [];</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  for (const entry of entries) {</span></span>
<span class="line"><span>    const fullPath = path.join(</span></span>
<span class="line"><span>      directory,</span></span>
<span class="line"><span>      entry.name</span></span>
<span class="line"><span>    );</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    if (entry.isDirectory()) {</span></span>
<span class="line"><span>      const children = await listFiles(fullPath);</span></span>
<span class="line"><span>      results.push(</span></span>
<span class="line"><span>        ...children.map((child) =&gt;</span></span>
<span class="line"><span>          path.join(entry.name, child)</span></span>
<span class="line"><span>        )</span></span>
<span class="line"><span>      );</span></span>
<span class="line"><span>    } else {</span></span>
<span class="line"><span>      results.push(entry.name);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  return results;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br></div></div><p>这里的 <code>listFiles</code> 是一个简化的目录读取示例。实际 Agent 通常还会过滤 <code>node_modules</code>、<code>.git</code>、构建产物等目录，并限制扫描深度。</p><p>需要注意：这段代码是真正执行目录读取的程序，不是大模型本身。</p><p>Agent 会把获取到的目录信息交给模型，让模型进一步判断哪些文件值得读取。</p><h3 id="_2-2-第二步-查找相关代码" tabindex="-1">2.2 第二步：查找相关代码 <a class="header-anchor" href="#_2-2-第二步-查找相关代码" aria-label="Permalink to &quot;2.2 第二步：查找相关代码&quot;">​</a></h3><p>AI 可能优先查看以下文件：</p><ul><li><code>App.tsx</code>：了解页面和路由的组织方式。</li><li><code>services/auth.ts</code>：了解项目是否已经封装登录接口。</li><li><code>AGENTS.md</code>：了解项目的开发约定。</li><li><code>package.json</code>：了解技术栈、依赖和可用脚本。</li></ul><p>随后，Agent 使用文件读取工具获取这些文件的内容，并将相关信息传递给大模型。</p><p>如果发现项目已经有登录接口，模型就可以复用它，而不是重新编写一套接口调用逻辑。</p><h3 id="_2-3-为什么-ai-不需要读取整个项目" tabindex="-1">2.3 为什么 AI 不需要读取整个项目？ <a class="header-anchor" href="#_2-3-为什么-ai-不需要读取整个项目" aria-label="Permalink to &quot;2.3 为什么 AI 不需要读取整个项目？&quot;">​</a></h3><p>因为大型项目可能包含数千个文件，全部塞进模型上下文既浪费 Token，也可能超过上下文窗口限制。</p><p>因此，<code>AI Coding Agent</code> 通常需要进行上下文筛选：</p><ol><li>获取项目目录和关键配置。</li><li>根据任务搜索相关文件。</li><li>读取必要的代码片段。</li><li>根据代码引用继续追踪依赖。</li><li>将筛选后的上下文交给模型。</li></ol><p>这种方式可以理解为：先建立项目的基本认知，再围绕当前任务获取必要的信息。</p><p>不同的 AI 编程工具可能采用不同策略，例如文件搜索、语义检索、代码索引或直接读取文件。具体实现并不完全相同。</p><h2 id="三、大模型生成代码后-究竟是谁把代码写入项目的" tabindex="-1">三、大模型生成代码后，究竟是谁把代码写入项目的？ <a class="header-anchor" href="#三、大模型生成代码后-究竟是谁把代码写入项目的" aria-label="Permalink to &quot;三、大模型生成代码后，究竟是谁把代码写入项目的？&quot;">​</a></h2><p>这是整个流程中最关键的一环。</p><p>假设模型分析完项目后，生成了一个新的登录组件：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// src/pages/Login.tsx</span></span>
<span class="line"><span></span></span>
<span class="line"><span>import { useState } from &quot;react&quot;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>export default function Login() {</span></span>
<span class="line"><span>  const [username, setUsername] = useState(&quot;&quot;);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  return (</span></span>
<span class="line"><span>    &lt;main&gt;</span></span>
<span class="line"><span>      &lt;h1&gt;用户登录&lt;/h1&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      &lt;input</span></span>
<span class="line"><span>        value={username}</span></span>
<span class="line"><span>        onChange={(event) =&gt;</span></span>
<span class="line"><span>          setUsername(event.target.value)</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>        placeholder=&quot;请输入用户名&quot;</span></span>
<span class="line"><span>      /&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      &lt;button type=&quot;button&quot;&gt;</span></span>
<span class="line"><span>        登录</span></span>
<span class="line"><span>      &lt;/button&gt;</span></span>
<span class="line"><span>    &lt;/main&gt;</span></span>
<span class="line"><span>  );</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br></div></div><p>这时，代码可能只是 <strong>模型返回的文本内容</strong>。</p><p>如果没有后续的文件操作，代码并不会因为出现在模型的回答中，就自动成为项目里的 <code>Login.tsx</code> 文件。</p><p>那么，代码是如何真正保存下来的？</p><h3 id="_3-1-方式一-模型请求调用文件写入工具" tabindex="-1">3.1 方式一：模型请求调用文件写入工具 <a class="header-anchor" href="#_3-1-方式一-模型请求调用文件写入工具" aria-label="Permalink to &quot;3.1 方式一：模型请求调用文件写入工具&quot;">​</a></h3><p>Agent 可以向模型提供一个文件写入工具，例如：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>type WriteFileArgs = {</span></span>
<span class="line"><span>  path: string;</span></span>
<span class="line"><span>  content: string;</span></span>
<span class="line"><span>};</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>模型根据工具的参数定义，生成一个结构化调用请求，表达自己希望把代码写入哪个文件。</p><p>例如：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;name&quot;: &quot;writeFile&quot;,</span></span>
<span class="line"><span>  &quot;arguments&quot;: {</span></span>
<span class="line"><span>    &quot;path&quot;: &quot;src/pages/Login.tsx&quot;,</span></span>
<span class="line"><span>    &quot;content&quot;: &quot;export default function Login() { ... }&quot;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>这里需要区分两个动作：</p><ul><li>模型生成工具调用请求：决定调用什么工具、使用什么参数。</li><li>Agent 执行工具调用：校验请求，并由真实的程序执行文件写入。</li></ul><p>上面的 JSON 只是示意，实际工具调用的消息结构由所使用的模型 API 决定。</p><h3 id="_3-2-方式二-本地程序真正写入文件" tabindex="-1">3.2 方式二：本地程序真正写入文件 <a class="header-anchor" href="#_3-2-方式二-本地程序真正写入文件" aria-label="Permalink to &quot;3.2 方式二：本地程序真正写入文件&quot;">​</a></h3><p>假设 Agent 运行在开发者电脑上，并且拥有项目目录的写入权限，那么它可以使用 Node.js 将代码保存到本地。</p><p>下面是一个简化的文件写入实现：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import {</span></span>
<span class="line"><span>  mkdir,</span></span>
<span class="line"><span>  writeFile,</span></span>
<span class="line"><span>} from &quot;node:fs/promises&quot;;</span></span>
<span class="line"><span>import path from &quot;node:path&quot;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>async function writeProjectFile(</span></span>
<span class="line"><span>  projectRoot: string,</span></span>
<span class="line"><span>  relativePath: string,</span></span>
<span class="line"><span>  content: string</span></span>
<span class="line"><span>): Promise&lt;void&gt; {</span></span>
<span class="line"><span>  const root = path.resolve(projectRoot);</span></span>
<span class="line"><span>  const target = path.resolve(</span></span>
<span class="line"><span>    root,</span></span>
<span class="line"><span>    relativePath</span></span>
<span class="line"><span>  );</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  const relative = path.relative(root, target);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  if (</span></span>
<span class="line"><span>    relative === &quot;..&quot; ||</span></span>
<span class="line"><span>    relative.startsWith(\`..\${path.sep}\`) ||</span></span>
<span class="line"><span>    path.isAbsolute(relative)</span></span>
<span class="line"><span>  ) {</span></span>
<span class="line"><span>    throw new Error(&quot;禁止写入项目目录之外的文件&quot;);</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  await mkdir(path.dirname(target), {</span></span>
<span class="line"><span>    recursive: true,</span></span>
<span class="line"><span>  });</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  await writeFile(target, content, &quot;utf8&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br></div></div><p>当 Agent 调用：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>await writeProjectFile(</span></span>
<span class="line"><span>  &quot;D:/MyProjects/my-app&quot;,</span></span>
<span class="line"><span>  &quot;src/pages/Login.tsx&quot;,</span></span>
<span class="line"><span>  generatedCode</span></span>
<span class="line"><span>);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>程序才会真正执行文件写入操作。</p><p>这里的 <code>generatedCode</code> 代表模型生成并经过应用程序接收的代码内容。</p><p>这段示例展示了基本的目录约束，但生产环境还需要考虑符号链接、文件覆盖、并发修改、权限检查和写入前审批等问题，不能只依赖路径字符串校验。</p><h3 id="_3-3-所以-ai-生成的代码一定会写入本地吗" tabindex="-1">3.3 所以，AI 生成的代码一定会写入本地吗？ <a class="header-anchor" href="#_3-3-所以-ai-生成的代码一定会写入本地吗" aria-label="Permalink to &quot;3.3 所以，AI 生成的代码一定会写入本地吗？&quot;">​</a></h3><p>不一定，关键取决于 Agent 的运行位置和执行方式。</p><table tabindex="0"><thead><tr><th>运行模式</th><th>代码通常写入哪里</th></tr></thead><tbody><tr><td>本地 AI 编程工具</td><td>开发者电脑上的项目目录</td></tr><tr><td>云端开发环境</td><td>远程容器或云端工作区</td></tr><tr><td>浏览器代码编辑器</td><td>浏览器工作区、远程服务或关联存储</td></tr><tr><td>仅聊天的 AI</td><td>通常只返回代码文本，不会直接修改项目</td></tr></tbody></table><p>因此，不能简单地认为“大模型生成代码，然后模型自己保存文件”。</p><p>更准确的描述是：</p><p>大模型生成代码或提出文件修改请求，拥有相应权限的 Agent 运行环境负责执行写入操作。</p><p>这也解释了为什么某些 AI 工具可以直接修改本地项目，而另一些工具只能给出代码片段供开发者复制。</p><h2 id="四、ai-为什么有时直接创建文件-有时却只修改几行" tabindex="-1">四、AI 为什么有时直接创建文件，有时却只修改几行？ <a class="header-anchor" href="#四、ai-为什么有时直接创建文件-有时却只修改几行" aria-label="Permalink to &quot;四、AI 为什么有时直接创建文件，有时却只修改几行？&quot;">​</a></h2><p>实际开发中，<code>AI Coding Agent</code> 并不总是把整个文件重新生成一遍。</p><p>常见的代码修改方式主要有三种。</p><h3 id="_4-1-直接创建或覆盖文件" tabindex="-1">4.1 直接创建或覆盖文件 <a class="header-anchor" href="#_4-1-直接创建或覆盖文件" aria-label="Permalink to &quot;4.1 直接创建或覆盖文件&quot;">​</a></h3><p>当需要创建新页面、生成配置文件，或者整个文件都需要重新组织时，Agent 可以使用文件写入工具。</p><p>例如：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/pages/Login.tsx</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>如果文件不存在，就创建新文件；如果文件已经存在，则可能覆盖原有内容。</p><p>这种方式实现简单，但覆盖文件可能丢失已有逻辑，因此必须谨慎处理。</p><h3 id="_4-2-使用-diff-patch-修改部分代码" tabindex="-1">4.2 使用 Diff / Patch 修改部分代码 <a class="header-anchor" href="#_4-2-使用-diff-patch-修改部分代码" aria-label="Permalink to &quot;4.2 使用 Diff / Patch 修改部分代码&quot;">​</a></h3><p>当只需要修改一个函数或增加一项配置时，使用差异补丁往往更加合适。</p><p>例如，原代码是：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>function getUserName() {</span></span>
<span class="line"><span>  return &quot;Guest&quot;;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>需求是把默认用户名改为 <code>Anonymous</code>。</p><p>Agent 可以生成类似这样的修改差异：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> function getUserName() {</span></span>
<span class="line"><span>-  return &quot;Guest&quot;;</span></span>
<span class="line"><span>+  return &quot;Anonymous&quot;;</span></span>
<span class="line"><span> }</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>Agent 再由补丁应用程序定位原始代码，并应用修改。</p><p>这种方式有几个优点：</p><ul><li>修改范围更明确。</li><li>更容易查看变更前后的差异。</li><li>更容易发现意外删除或覆盖。</li><li>更方便在修改前后进行审查。</li></ul><p>不过，补丁也可能因为原文件发生变化、匹配内容不唯一或上下文不一致而应用失败。因此，成熟的实现需要检查补丁是否匹配预期，并在失败时重新读取文件或重新生成修改方案。</p><h3 id="_4-3-通过编辑器或代码操作接口修改" tabindex="-1">4.3 通过编辑器或代码操作接口修改 <a class="header-anchor" href="#_4-3-通过编辑器或代码操作接口修改" aria-label="Permalink to &quot;4.3 通过编辑器或代码操作接口修改&quot;">​</a></h3><p>有些工具会通过编辑器 API、语言服务或专门的代码编辑接口修改文件。</p><p>例如，Agent 可能只提交一个编辑请求：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;file&quot;: &quot;src/pages/Login.tsx&quot;,</span></span>
<span class="line"><span>  &quot;operation&quot;: &quot;replace&quot;,</span></span>
<span class="line"><span>  &quot;oldText&quot;: &quot;return &#39;Guest&#39;;&quot;,</span></span>
<span class="line"><span>  &quot;newText&quot;: &quot;return &#39;Anonymous&#39;;&quot;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>执行程序会检查旧内容是否存在，再决定是否应用修改。</p><p>需要注意，以上只是示意性的编辑接口，并不是某个特定 AI 编程工具的通用协议。</p><p>选择哪种修改方式，通常取决于任务规模、工具能力、代码结构和修改风险。 创建新文件可以直接写入，而已有复杂文件通常更适合精确修改并检查差异。</p><h2 id="五、代码写入后-ai-为什么还要运行测试" tabindex="-1">五、代码写入后，AI 为什么还要运行测试？ <a class="header-anchor" href="#五、代码写入后-ai-为什么还要运行测试" aria-label="Permalink to &quot;五、代码写入后，AI 为什么还要运行测试？&quot;">​</a></h2><p>文件保存成功，并不意味着功能已经实现。</p><p>新代码可能存在语法错误、类型错误、接口参数不匹配，或者与现有组件发生冲突。</p><p>例如，AI 创建了登录页面，却忘记将它加入路由配置。文件本身没有问题，但用户仍然无法通过应用正常访问这个页面。</p><p>因此，<code>AI Coding Agent</code> 通常还会调用终端工具，运行项目中的检查命令。</p><p>对于一个 TypeScript 项目，可能执行：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npm run lint</span></span>
<span class="line"><span>npm run typecheck</span></span>
<span class="line"><span>npm test</span></span>
<span class="line"><span>npm run build</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>这些命令只是示例，实际能否执行取决于 <code>package.json</code> 中定义的脚本。</p><p>如果构建失败，Agent 可能拿到这样的结果：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/pages/Login.tsx:18:10</span></span>
<span class="line"><span></span></span>
<span class="line"><span>error TS2304:</span></span>
<span class="line"><span>Cannot find name &#39;loginUser&#39;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>模型接收到错误信息后，可以进一步读取相关文件，判断是否遗漏了接口导入、函数定义或其他依赖，然后再次提交修改。</p><p>完整的流程可能变成：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>生成或修改代码</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>保存到项目文件</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>运行测试或构建</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>读取执行结果</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ├── 验证失败 ──▶ 分析错误并再次修改，回到「生成或修改代码」</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>   验证通过</span></span>
<span class="line"><span>继续完成任务</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div><p>这就是前一篇文章中介绍的 <code>Agent Loop</code> 在 AI 编程场景下的具体应用。</p><p>模型不只是生成一段代码就结束，而是利用真实的运行结果判断是否需要继续行动。</p><p>当然，自动修复也不是无限可靠的。模型可能误解错误信息，或者修改后引入新的问题。因此，自动化流程需要限制重试次数，并尽可能通过测试、类型检查和人工审查确认结果。</p><h2 id="六、ai-修改项目代码时-如何避免误操作" tabindex="-1">六、AI 修改项目代码时，如何避免误操作？ <a class="header-anchor" href="#六、ai-修改项目代码时-如何避免误操作" aria-label="Permalink to &quot;六、AI 修改项目代码时，如何避免误操作？&quot;">​</a></h2><p>既然 Agent 能够读写文件、运行命令，那么它就可能覆盖重要代码、删除文件，甚至执行有风险的操作。</p><p>因此，生产级 <code>AI Coding Agent</code> 需要在执行能力之外建立安全机制。</p><h3 id="_6-1-限制文件访问范围" tabindex="-1">6.1 限制文件访问范围 <a class="header-anchor" href="#_6-1-限制文件访问范围" aria-label="Permalink to &quot;6.1 限制文件访问范围&quot;">​</a></h3><p>不要让 <code>Agent</code> 无条件访问整台电脑。</p><p>更合理的做法是将可操作范围限制在明确的项目工作区内，并针对敏感文件设置额外限制。</p><p>例如：</p><ul><li>允许修改 <code>src/</code> 下的业务代码。</li><li>对 <code>.env</code>、私钥和凭据文件设置访问限制。</li><li>禁止随意修改 <code>.git/</code> 等内部目录。</li><li>对删除文件和批量覆盖操作进行额外确认。</li></ul><p>具体规则应根据开发场景设置，不能仅凭文件扩展名判断一个文件是否安全。</p><h3 id="_6-2-修改前保留差异记录" tabindex="-1">6.2 修改前保留差异记录 <a class="header-anchor" href="#_6-2-修改前保留差异记录" aria-label="Permalink to &quot;6.2 修改前保留差异记录&quot;">​</a></h3><p>对于已有文件，建议在修改前后生成 Diff，让开发者能够快速查看：</p><ul><li>新增了哪些代码。</li><li>删除了哪些代码。</li><li>哪些文件被修改。</li><li>是否存在超出任务范围的变更。</li></ul><p>结合 Git 分支、提交记录或临时快照，可以进一步降低误修改带来的恢复成本。</p><h3 id="_6-3-对高风险命令进行人工审批" tabindex="-1">6.3 对高风险命令进行人工审批 <a class="header-anchor" href="#_6-3-对高风险命令进行人工审批" aria-label="Permalink to &quot;6.3 对高风险命令进行人工审批&quot;">​</a></h3><p>例如，读取项目文件和运行普通测试，与删除目录、修改生产配置、部署线上服务，具有完全不同的风险。</p><p>可以根据命令类型、目标目录和执行环境设置不同的权限等级。</p><p>尤其需要注意：模型认为某个操作有必要，不代表这个操作就应该被允许执行。</p><p>权限校验必须由 Agent 运行环境执行，而不能仅依赖模型自觉遵守提示词。</p><h2 id="七、总结-ai-coding-agent-修改代码的完整链路" tabindex="-1">七、总结：AI Coding Agent 修改代码的完整链路 <a class="header-anchor" href="#七、总结-ai-coding-agent-修改代码的完整链路" aria-label="Permalink to &quot;七、总结：AI Coding Agent 修改代码的完整链路&quot;">​</a></h2><p>回到最初的问题：AI 生成的代码究竟是怎么进入项目的？</p><p>整个过程可以归纳为以下几个步骤：</p><ol><li>理解需求：模型分析用户希望实现的功能。</li><li>获取上下文：Agent 读取项目结构、相关代码和开发规范。</li><li>生成修改方案：模型决定创建哪些文件，或修改哪些代码。</li><li>调用编辑工具：模型通过工具调用请求表达修改意图。</li><li>执行文件操作：Agent Runtime 校验权限，并由实际程序写入文件或应用补丁。</li><li>运行验证：Agent 调用测试、Lint、类型检查或构建命令。</li><li>根据反馈迭代：如果出现错误，将执行结果交给模型分析，必要时继续修改。</li><li>结束任务：达到完成条件或触发停止规则后，向用户汇报结果。</li></ol><p>理解这条链路之后，就会发现 <code>AI Coding Agent</code> 并不只是一个更强大的代码生成器。</p><p>它真正的价值在于将大模型的理解与生成能力，和文件系统、开发工具、执行环境及验证机制结合起来，让 AI 能够在一个受控的工作环境中持续推进开发任务。</p>`,137))])}const f=p(b,[["render",o]]);export{q as __pageData,f as default};
